   120	.demo-wrap  { background: var(--white); border: 1px solid var(--border); border-radius: 10px; padding: 24px 28px; }
   121	.demo-intro { font-size: 13px; color: var(--muted); margin-bottom: 20px; line-height: 1.6; }
