<script>
let cur = 0;
const panels = document.querySelectorAll('.panel');
const tabs = document.querySelectorAll('nav button');
function show(i) {
  panels.forEach((p, idx) => p.classList.toggle('active', idx === i));
  tabs.forEach((b, idx) => b.setAttribute('aria-selected', idx === i ? 'true' : 'false'));
  cur = i;
  document.getElementById('content').scrollTop = 0;
}
tabs.forEach((btn, i) => btn.addEventListener('click', () => show(i)));
document.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight' && cur < panels.length - 1) show(cur + 1);
